EMBEDDED_SAMPLE_FILES: Dict[str, str] = {
  "auth.py": "\"\"\"\nAuthentication and authorization utilities.\n\"\"\"\nfrom typing import Optional\nfrom models import User, UserRole, Order\n\n\nclass AuthError(Exception):\n    def __init__(self, message: str, code: str = \"AUTH_ERROR\"):\n        self.message = message\n        self.code = code\n        super().__init__(message)\n\n\nclass PermissionError(Exception):\n    def __init__(self, message: str, required_role: Optional[UserRole] = None):\n        self.message = message\n        self.required_role = required_role\n        super().__init__(message)\n\n\n# Simulated token store (in production, use JWT or session store)\n_active_tokens: dict[str, str] = {}  # token -> user_id\n_users: dict[str, User] = {}         # user_id -> User\n\n\ndef register_user(user: User, token: str) -> None:\n    \"\"\"Register a user and their session token.\"\"\"\n    _users[user.id] = user\n    _active_tokens[token] = user.id\n\n\ndef get_current_user(token: str) -> User:\n    \"\"\"Resolve a token to a User, raising AuthError if invalid.\"\"\"\n    user_id = _active_tokens.get(token)\n    if not user_id:\n        raise AuthError(\"Invalid or expired token\", code=\"INVALID_TOKEN\")\n    user = _users.get(user_id)\n    if not user:\n        raise AuthError(\"User not found\", code=\"USER_NOT_FOUND\")\n    if not user.is_active:\n        raise AuthError(\"Account is deactivated\", code=\"ACCOUNT_INACTIVE\")\n    return user\n\n\ndef require_role(user: User, *roles: UserRole) -> None:\n    \"\"\"Assert that the user holds at least one of the given roles.\"\"\"\n    if user.role not in roles:\n        raise PermissionError(\n            f\"Action requires one of: {[r.value for r in roles]}\",\n            required_role=roles[0] if roles else None,\n        )\n\n\ndef can_modify_order(user: User, order: Order) -> bool:\n    \"\"\"\n    Determine if the user can modify an order.\n    Admins and support can always modify.\n    Customers can only modify their own orders.\n    \"\"\"\n    if user.role in (UserRole.ADMIN, UserRole.SUPPORT):\n        return True\n    return order.user_id == user.id\n\n\ndef can_apply_discount(user: User) -> bool:\n    \"\"\"Only admins can apply discounts.\"\"\"\n    return user.role == UserRole.ADMIN\n",
  "demo_change.diff": "--- a/services/order_service.py\n+++ b/services/order_service.py\n@@ -44,8 +44,10 @@ class OrderService:\n \n     def update_order(self, user: User, order_id: str, request: UpdateOrderRequest) -> Order:\n         order = self._repo.get(order_id)\n \n         if not can_modify_order(user, order):\n             raise PermissionError(\"You do not have permission to modify this order\")\n \n-        if not order.can_be_updated():\n-            raise OrderValidationError(\n-                f\"Order in status '{order.status.value}' cannot be updated\"\n-            )\n+        # Allow updates on both pending and confirmed orders to support\n+        # last-minute item corrections before shipping\n+        if order.status not in (OrderStatus.PENDING, OrderStatus.CONFIRMED):\n+            raise OrderValidationError(\n+                f\"Order in status '{order.status.value}' cannot be updated\"\n+            )\n",
  "models.py": "\"\"\"\nDomain models for the Demo Orders project.\n\"\"\"\nfrom dataclasses import dataclass, field\nfrom datetime import datetime, timezone\n\ndef _now():\n    return datetime.now(timezone.utc).replace(tzinfo=None)\nfrom enum import Enum\nfrom typing import List, Optional\n\n\nclass OrderStatus(Enum):\n    PENDING = \"pending\"\n    CONFIRMED = \"confirmed\"\n    SHIPPED = \"shipped\"\n    DELIVERED = \"delivered\"\n    CANCELLED = \"cancelled\"\n\n\nclass UserRole(Enum):\n    CUSTOMER = \"customer\"\n    ADMIN = \"admin\"\n    SUPPORT = \"support\"\n\n\n@dataclass\nclass User:\n    id: str\n    email: str\n    role: UserRole\n    is_active: bool = True\n    created_at: datetime = field(default_factory=_now)\n\n\n@dataclass\nclass OrderItem:\n    product_id: str\n    product_name: str\n    quantity: int\n    unit_price: float\n\n    @property\n    def subtotal(self) -> float:\n        return self.quantity * self.unit_price\n\n\n@dataclass\nclass Order:\n    id: str\n    user_id: str\n    items: List[OrderItem]\n    status: OrderStatus\n    created_at: datetime = field(default_factory=_now)\n    updated_at: datetime = field(default_factory=_now)\n    discount_percent: float = 0.0\n    notes: Optional[str] = None\n\n    @property\n    def subtotal(self) -> float:\n        return sum(item.subtotal for item in self.items)\n\n    @property\n    def total(self) -> float:\n        return self.subtotal * (1 - self.discount_percent / 100)\n\n    def can_be_cancelled(self) -> bool:\n        return self.status in (OrderStatus.PENDING, OrderStatus.CONFIRMED)\n\n    def can_be_updated(self) -> bool:\n        \"\"\"Only pending orders can be updated by customers.\"\"\"\n        return self.status == OrderStatus.PENDING\n\n\n@dataclass\nclass UpdateOrderRequest:\n    items: Optional[List[OrderItem]] = None\n    discount_percent: Optional[float] = None\n    notes: Optional[str] = None\n    status: Optional[OrderStatus] = None\n",
  "README.md": "# Demo Orders\n\nA sample e-commerce order management service used as the target project for DevTwin analysis demonstrations.\n\n## Architecture\n\n```\napi/routes.py          \u2190 Flask HTTP handlers\nservices/order_service.py  \u2190 Business logic, validation, authorization\nrepositories/order_repository.py  \u2190 Data access layer\nauth.py                \u2190 Token authentication, permission checks\nmodels.py              \u2190 Domain models (Order, User, OrderItem, etc.)\ntests/                 \u2190 Pytest test suite\n```\n\n## Running Tests\n\n```bash\ncd sample_project\npip install pytest flask\npytest tests/ -v\n```\n\n## Prepared Demo Change\n\nThe change file `demo_change.diff` contains a realistic-looking but consequential modification:\n\n**Change:** Allow customers to update orders in `CONFIRMED` status (not just `PENDING`).\n\n**Hidden consequences:**\n- Authorization bypass: `can_modify_order` is now callable on confirmed orders by any customer\n- Discount application risk: confirmed orders with discounts can be retroactively modified\n- API contract violation: the PATCH endpoint now behaves differently for confirmed orders\n- Existing tests that assert `cannot_update_confirmed_order` will break\n- Status transition integrity is compromised\n\nThis is the kind of change DevTwin is designed to surface before merge.\n",
  "api/routes.py": "\"\"\"\nFlask API routes for the Demo Orders service.\n\"\"\"\nfrom flask import Flask, jsonify, request, abort\nfrom models import OrderItem, OrderStatus, UpdateOrderRequest\nfrom services.order_service import OrderService, OrderValidationError\nfrom auth import get_current_user, AuthError, PermissionError\nfrom repositories.order_repository import OrderRepository, OrderNotFoundError\n\napp = Flask(__name__)\n_repo = OrderRepository()\n_service = OrderService(_repo)\n\n\ndef _get_token() -> str:\n    auth_header = request.headers.get(\"Authorization\", \"\")\n    if not auth_header.startswith(\"Bearer \"):\n        abort(401, description=\"Missing or malformed Authorization header\")\n    return auth_header[7:]\n\n\n@app.errorhandler(AuthError)\ndef handle_auth_error(e):\n    return jsonify({\"error\": e.message, \"code\": e.code}), 401\n\n\n@app.errorhandler(PermissionError)\ndef handle_permission_error(e):\n    return jsonify({\"error\": e.message}), 403\n\n\n@app.errorhandler(OrderNotFoundError)\ndef handle_not_found(e):\n    return jsonify({\"error\": str(e)}), 404\n\n\n@app.errorhandler(OrderValidationError)\ndef handle_validation_error(e):\n    body = {\"error\": str(e)}\n    if e.field:\n        body[\"field\"] = e.field\n    return jsonify(body), 422\n\n\n@app.route(\"/orders\", methods=[\"GET\"])\ndef list_orders():\n    user = get_current_user(_get_token())\n    orders = _service.list_orders(user)\n    return jsonify([_serialize_order(o) for o in orders])\n\n\n@app.route(\"/orders\", methods=[\"POST\"])\ndef create_order():\n    user = get_current_user(_get_token())\n    data = request.get_json(force=True)\n    items = [\n        OrderItem(\n            product_id=i[\"product_id\"],\n            product_name=i[\"product_name\"],\n            quantity=i[\"quantity\"],\n            unit_price=i[\"unit_price\"],\n        )\n        for i in data.get(\"items\", [])\n    ]\n    order = _service.create_order(user, items)\n    return jsonify(_serialize_order(order)), 201\n\n\n@app.route(\"/orders/<order_id>\", methods=[\"GET\"])\ndef get_order(order_id: str):\n    user = get_current_user(_get_token())\n    order = _service.get_order(user, order_id)\n    return jsonify(_serialize_order(order))\n\n\n@app.route(\"/orders/<order_id>\", methods=[\"PATCH\"])\ndef update_order(order_id: str):\n    user = get_current_user(_get_token())\n    data = request.get_json(force=True)\n\n    req = UpdateOrderRequest(\n        items=[\n            OrderItem(\n                product_id=i[\"product_id\"],\n                product_name=i[\"product_name\"],\n                quantity=i[\"quantity\"],\n                unit_price=i[\"unit_price\"],\n            )\n            for i in data[\"items\"]\n        ] if \"items\" in data else None,\n        discount_percent=data.get(\"discount_percent\"),\n        notes=data.get(\"notes\"),\n        status=OrderStatus(data[\"status\"]) if \"status\" in data else None,\n    )\n    order = _service.update_order(user, order_id, req)\n    return jsonify(_serialize_order(order))\n\n\n@app.route(\"/orders/<order_id>/cancel\", methods=[\"POST\"])\ndef cancel_order(order_id: str):\n    user = get_current_user(_get_token())\n    order = _service.cancel_order(user, order_id)\n    return jsonify(_serialize_order(order))\n\n\ndef _serialize_order(order) -> dict:\n    return {\n        \"id\": order.id,\n        \"user_id\": order.user_id,\n        \"status\": order.status.value,\n        \"items\": [\n            {\n                \"product_id\": i.product_id,\n                \"product_name\": i.product_name,\n                \"quantity\": i.quantity,\n                \"unit_price\": i.unit_price,\n                \"subtotal\": i.subtotal,\n            }\n            for i in order.items\n        ],\n        \"subtotal\": order.subtotal,\n        \"total\": order.total,\n        \"discount_percent\": order.discount_percent,\n        \"notes\": order.notes,\n        \"created_at\": order.created_at.isoformat(),\n        \"updated_at\": order.updated_at.isoformat(),\n    }\n\n\nif __name__ == \"__main__\":\n    app.run(debug=True, port=5001)\n",
  "docs/architecture.md": "# Demo Orders Architecture\n\n## Component Overview\n\n### API Layer (`api/routes.py`)\n- Flask HTTP endpoints\n- Handles authentication token extraction\n- Delegates all business logic to OrderService\n- Error handlers convert domain exceptions to HTTP responses\n\n### Service Layer (`services/order_service.py`)\n- Core business logic\n- Order lifecycle management\n- Authorization delegation to `auth.py`\n- Validation rules enforced here\n\n### Repository Layer (`repositories/order_repository.py`)\n- Data access abstraction\n- In-memory storage (replaceable with DB)\n- No business logic\n\n### Auth Module (`auth.py`)\n- Token-based authentication\n- Role-based permission checks\n- `can_modify_order`: ownership + role check\n- `can_apply_discount`: admin-only gate\n\n### Models (`models.py`)\n- `Order.can_be_updated()`: status gate \u2192 PENDING only\n- `Order.can_be_cancelled()`: status gate \u2192 PENDING | CONFIRMED\n\n## Key Invariants\n\n1. Customers can only modify their own orders\n2. Only PENDING orders can be updated (item/notes changes)\n3. Only PENDING and CONFIRMED orders can be cancelled\n4. Only admins can apply discounts\n5. Discount is applied at update time and persists on the order\n\n## Status Transitions\n\n```\nPENDING \u2192 CONFIRMED \u2192 SHIPPED \u2192 DELIVERED\n       \u2193           \u2193\n   CANCELLED   CANCELLED\n```\n\nOnce shipped, no modifications or cancellations are allowed.\n",
  "repositories/order_repository.py": "\"\"\"\nOrder repository \u2014 data access layer.\n\"\"\"\nfrom typing import Dict, List, Optional\nfrom models import Order, OrderStatus\n\n\nclass OrderNotFoundError(Exception):\n    def __init__(self, order_id: str):\n        self.order_id = order_id\n        super().__init__(f\"Order not found: {order_id}\")\n\n\nclass OrderRepository:\n    \"\"\"In-memory order store (swap for a real DB in production).\"\"\"\n\n    def __init__(self) -> None:\n        self._store: Dict[str, Order] = {}\n\n    def save(self, order: Order) -> Order:\n        self._store[order.id] = order\n        return order\n\n    def get(self, order_id: str) -> Order:\n        order = self._store.get(order_id)\n        if order is None:\n            raise OrderNotFoundError(order_id)\n        return order\n\n    def list_by_user(self, user_id: str) -> List[Order]:\n        return [o for o in self._store.values() if o.user_id == user_id]\n\n    def list_by_status(self, status: OrderStatus) -> List[Order]:\n        return [o for o in self._store.values() if o.status == status]\n\n    def delete(self, order_id: str) -> None:\n        if order_id not in self._store:\n            raise OrderNotFoundError(order_id)\n        del self._store[order_id]\n\n    def count(self) -> int:\n        return len(self._store)\n",
  "services/order_service.py": "\"\"\"\nOrder service \u2014 business logic layer.\n\"\"\"\nfrom datetime import datetime, timezone\n\ndef _now():\n    return datetime.now(timezone.utc).replace(tzinfo=None)\nfrom typing import List, Optional\n\nfrom models import Order, OrderItem, OrderStatus, UpdateOrderRequest, User\nfrom auth import can_modify_order, can_apply_discount, PermissionError\nfrom repositories.order_repository import OrderRepository, OrderNotFoundError\n\n\nclass OrderValidationError(Exception):\n    def __init__(self, message: str, field: Optional[str] = None):\n        self.field = field\n        super().__init__(message)\n\n\nclass OrderService:\n\n    def __init__(self, repository: OrderRepository) -> None:\n        self._repo = repository\n\n    def create_order(self, user: User, items: List[OrderItem]) -> Order:\n        if not items:\n            raise OrderValidationError(\"Order must contain at least one item\", field=\"items\")\n        for item in items:\n            if item.quantity <= 0:\n                raise OrderValidationError(\n                    f\"Item quantity must be positive: {item.product_id}\", field=\"quantity\"\n                )\n            if item.unit_price < 0:\n                raise OrderValidationError(\n                    f\"Item price cannot be negative: {item.product_id}\", field=\"unit_price\"\n                )\n\n        order = Order(\n            id=self._generate_id(),\n            user_id=user.id,\n            items=items,\n            status=OrderStatus.PENDING,\n        )\n        return self._repo.save(order)\n\n    def update_order(self, user: User, order_id: str, request: UpdateOrderRequest) -> Order:\n        order = self._repo.get(order_id)\n\n        if not can_modify_order(user, order):\n            raise PermissionError(\"You do not have permission to modify this order\")\n\n        if not order.can_be_updated():\n            raise OrderValidationError(\n                f\"Order in status '{order.status.value}' cannot be updated\"\n            )\n\n        if request.items is not None:\n            if not request.items:\n                raise OrderValidationError(\"Updated order must contain at least one item\", field=\"items\")\n            order.items = request.items\n\n        if request.discount_percent is not None:\n            if not can_apply_discount(user):\n                raise PermissionError(\"Only admins can apply discounts\")\n            if not (0 <= request.discount_percent <= 100):\n                raise OrderValidationError(\"Discount must be between 0 and 100\", field=\"discount_percent\")\n            order.discount_percent = request.discount_percent\n\n        if request.notes is not None:\n            order.notes = request.notes\n\n        if request.status is not None:\n            order.status = request.status\n\n        order.updated_at = _now()\n        return self._repo.save(order)\n\n    def cancel_order(self, user: User, order_id: str) -> Order:\n        order = self._repo.get(order_id)\n\n        if not can_modify_order(user, order):\n            raise PermissionError(\"You do not have permission to cancel this order\")\n\n        if not order.can_be_cancelled():\n            raise OrderValidationError(\n                f\"Order in status '{order.status.value}' cannot be cancelled\"\n            )\n\n        order.status = OrderStatus.CANCELLED\n        order.updated_at = _now()\n        return self._repo.save(order)\n\n    def get_order(self, user: User, order_id: str) -> Order:\n        order = self._repo.get(order_id)\n        if not can_modify_order(user, order):\n            raise PermissionError(\"You do not have access to this order\")\n        return order\n\n    def list_orders(self, user: User) -> List[Order]:\n        from models import UserRole\n        if user.role in (UserRole.ADMIN, UserRole.SUPPORT):\n            return list(self._repo._store.values())\n        return self._repo.list_by_user(user.id)\n\n    @staticmethod\n    def _generate_id() -> str:\n        import uuid\n        return str(uuid.uuid4())\n",
  "tests/test_auth.py": "\"\"\"\nTests for authentication and authorization utilities.\n\"\"\"\nimport sys\nimport os\nsys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))\n\nimport pytest\nfrom models import User, UserRole, Order, OrderStatus, OrderItem\nfrom auth import (\n    get_current_user, register_user, require_role,\n    can_modify_order, can_apply_discount, AuthError, PermissionError\n)\n\n\ndef make_order(user_id: str = \"u1\") -> Order:\n    return Order(\n        id=\"ord1\",\n        user_id=user_id,\n        items=[OrderItem(\"p1\", \"Widget\", 1, 10.0)],\n        status=OrderStatus.PENDING,\n    )\n\n\nclass TestTokenAuth:\n    def test_valid_token_returns_user(self):\n        user = User(id=\"u100\", email=\"test@example.com\", role=UserRole.CUSTOMER)\n        register_user(user, \"valid_token_100\")\n        result = get_current_user(\"valid_token_100\")\n        assert result.id == \"u100\"\n\n    def test_invalid_token_raises_auth_error(self):\n        with pytest.raises(AuthError) as exc_info:\n            get_current_user(\"nonexistent_token_xyz\")\n        assert exc_info.value.code == \"INVALID_TOKEN\"\n\n    def test_inactive_user_raises_auth_error(self):\n        user = User(id=\"u101\", email=\"inactive@example.com\", role=UserRole.CUSTOMER, is_active=False)\n        register_user(user, \"inactive_token_101\")\n        with pytest.raises(AuthError) as exc_info:\n            get_current_user(\"inactive_token_101\")\n        assert exc_info.value.code == \"ACCOUNT_INACTIVE\"\n\n\nclass TestRequireRole:\n    def test_matching_role_passes(self):\n        admin = User(id=\"a1\", email=\"admin@example.com\", role=UserRole.ADMIN)\n        require_role(admin, UserRole.ADMIN)  # should not raise\n\n    def test_non_matching_role_raises(self):\n        customer = User(id=\"c1\", email=\"c@example.com\", role=UserRole.CUSTOMER)\n        with pytest.raises(PermissionError):\n            require_role(customer, UserRole.ADMIN)\n\n    def test_multiple_acceptable_roles(self):\n        support = User(id=\"s1\", email=\"s@example.com\", role=UserRole.SUPPORT)\n        require_role(support, UserRole.ADMIN, UserRole.SUPPORT)  # should not raise\n\n\nclass TestCanModifyOrder:\n    def test_owner_customer_can_modify(self):\n        customer = User(id=\"u1\", email=\"c@example.com\", role=UserRole.CUSTOMER)\n        order = make_order(user_id=\"u1\")\n        assert can_modify_order(customer, order) is True\n\n    def test_non_owner_customer_cannot_modify(self):\n        stranger = User(id=\"u2\", email=\"other@example.com\", role=UserRole.CUSTOMER)\n        order = make_order(user_id=\"u1\")\n        assert can_modify_order(stranger, order) is False\n\n    def test_admin_can_modify_any_order(self):\n        admin = User(id=\"admin\", email=\"admin@example.com\", role=UserRole.ADMIN)\n        order = make_order(user_id=\"some_customer\")\n        assert can_modify_order(admin, order) is True\n\n    def test_support_can_modify_any_order(self):\n        support = User(id=\"sup1\", email=\"sup@example.com\", role=UserRole.SUPPORT)\n        order = make_order(user_id=\"some_customer\")\n        assert can_modify_order(support, order) is True\n\n\nclass TestCanApplyDiscount:\n    def test_admin_can_apply_discount(self):\n        admin = User(id=\"a1\", email=\"admin@example.com\", role=UserRole.ADMIN)\n        assert can_apply_discount(admin) is True\n\n    def test_customer_cannot_apply_discount(self):\n        customer = User(id=\"c1\", email=\"c@example.com\", role=UserRole.CUSTOMER)\n        assert can_apply_discount(customer) is False\n\n    def test_support_cannot_apply_discount(self):\n        support = User(id=\"s1\", email=\"s@example.com\", role=UserRole.SUPPORT)\n        assert can_apply_discount(support) is False\n",
  "tests/test_orders.py": "\"\"\"\nTests for order service business logic.\n\"\"\"\nimport sys\nimport os\nsys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))\n\nimport pytest\nfrom models import User, UserRole, OrderItem, OrderStatus, UpdateOrderRequest\nfrom services.order_service import OrderService, OrderValidationError\nfrom auth import PermissionError, register_user\nfrom repositories.order_repository import OrderRepository, OrderNotFoundError\n\n\ndef make_repo_and_service():\n    repo = OrderRepository()\n    service = OrderService(repo)\n    return repo, service\n\n\ndef make_customer(user_id: str = \"u1\") -> User:\n    return User(id=user_id, email=f\"{user_id}@example.com\", role=UserRole.CUSTOMER)\n\n\ndef make_admin(user_id: str = \"admin1\") -> User:\n    return User(id=user_id, email=\"admin@example.com\", role=UserRole.ADMIN)\n\n\ndef make_items():\n    return [OrderItem(product_id=\"p1\", product_name=\"Widget\", quantity=2, unit_price=9.99)]\n\n\nclass TestCreateOrder:\n    def test_creates_pending_order(self):\n        _, service = make_repo_and_service()\n        customer = make_customer()\n        order = service.create_order(customer, make_items())\n        assert order.status == OrderStatus.PENDING\n        assert order.user_id == \"u1\"\n\n    def test_raises_on_empty_items(self):\n        _, service = make_repo_and_service()\n        with pytest.raises(OrderValidationError):\n            service.create_order(make_customer(), [])\n\n    def test_raises_on_negative_quantity(self):\n        _, service = make_repo_and_service()\n        items = [OrderItem(\"p1\", \"Widget\", -1, 10.0)]\n        with pytest.raises(OrderValidationError):\n            service.create_order(make_customer(), items)\n\n    def test_raises_on_negative_price(self):\n        _, service = make_repo_and_service()\n        items = [OrderItem(\"p1\", \"Widget\", 1, -5.0)]\n        with pytest.raises(OrderValidationError):\n            service.create_order(make_customer(), items)\n\n\nclass TestUpdateOrder:\n    def test_customer_can_update_own_pending_order(self):\n        _, service = make_repo_and_service()\n        customer = make_customer()\n        order = service.create_order(customer, make_items())\n        new_items = [OrderItem(\"p2\", \"Gadget\", 1, 19.99)]\n        updated = service.update_order(customer, order.id, UpdateOrderRequest(items=new_items))\n        assert updated.items[0].product_id == \"p2\"\n\n    def test_customer_cannot_update_others_order(self):\n        _, service = make_repo_and_service()\n        owner = make_customer(\"owner\")\n        stranger = make_customer(\"stranger\")\n        order = service.create_order(owner, make_items())\n        with pytest.raises(PermissionError):\n            service.update_order(stranger, order.id, UpdateOrderRequest(notes=\"hi\"))\n\n    def test_cannot_update_confirmed_order(self):\n        repo, service = make_repo_and_service()\n        customer = make_customer()\n        order = service.create_order(customer, make_items())\n        # Manually advance status\n        order.status = OrderStatus.CONFIRMED\n        repo.save(order)\n        with pytest.raises(OrderValidationError):\n            service.update_order(customer, order.id, UpdateOrderRequest(notes=\"too late\"))\n\n    def test_admin_can_apply_discount(self):\n        _, service = make_repo_and_service()\n        customer = make_customer()\n        admin = make_admin()\n        order = service.create_order(customer, make_items())\n        updated = service.update_order(admin, order.id, UpdateOrderRequest(discount_percent=10.0))\n        assert updated.discount_percent == 10.0\n\n    def test_customer_cannot_apply_discount(self):\n        _, service = make_repo_and_service()\n        customer = make_customer()\n        order = service.create_order(customer, make_items())\n        with pytest.raises(PermissionError):\n            service.update_order(customer, order.id, UpdateOrderRequest(discount_percent=10.0))\n\n\nclass TestCancelOrder:\n    def test_can_cancel_pending_order(self):\n        _, service = make_repo_and_service()\n        customer = make_customer()\n        order = service.create_order(customer, make_items())\n        cancelled = service.cancel_order(customer, order.id)\n        assert cancelled.status == OrderStatus.CANCELLED\n\n    def test_cannot_cancel_shipped_order(self):\n        repo, service = make_repo_and_service()\n        customer = make_customer()\n        order = service.create_order(customer, make_items())\n        order.status = OrderStatus.SHIPPED\n        repo.save(order)\n        with pytest.raises(OrderValidationError):\n            service.cancel_order(customer, order.id)\n"
}
